// Turns the configured "stale after N hours" window into a concrete
// ISO timestamp we can hand straight to PostgREST as a `lt.` filter.

const config = $('⚙️ Configuration').first().json;
const cutoffTimestamp = new Date(Date.now() - config.staleHours * 60 * 60 * 1000).toISOString();

return [{
  json: {
    ...config,
    cutoffTimestamp
  }
}];

// Normalises the HTTP Request node's output into a single item holding
// a `claims` array + count, regardless of whether n8n auto-split the
// JSON array response into multiple items or returned it as one item
// containing the whole array.

const raw = $input.all();
let claims;

if (raw.length === 1 && Array.isArray(raw[0].json)) {
  claims = raw[0].json;
} else {
  claims = raw.map(i => i.json).filter(j => j && Object.keys(j).length > 0);
}

return [{
  json: {
    claims,
    count: claims.length
  }
}];

// Builds the HTML body for the admin "pending verification" chaser digest.
// Adjust the field names below (alumni_name, alumni_email, track_id, ...)
// to match your actual `verification_claims` columns if they differ -
// see the README for how to embed the related alumni record via
// PostgREST's `select=*,...` resource embedding instead.

const { claims } = $json;
const config = $('⚙️ Configuration').first().json;

function hoursPending(createdAt) {
  const ms = Date.now() - new Date(createdAt).getTime();
  return Math.floor(ms / (1000 * 60 * 60));
}

const rows = claims.map(c => {
  // verification_claims has no name/email column itself - the select query
  // embeds them from profiles via the user_id FK (verified against the live
  // schema 2026-09-16). Fallbacks kept in case a differently-shaped table
  // is used instead.
  const profile = c.profiles || {};
  const name    = [profile.first_name, profile.last_name].filter(Boolean).join(' ') || c.alumni_name || c.full_name || c.name || '(name unavailable)';
  const email   = profile.email || c.alumni_email || c.email || '(email unavailable)';
  const trackId = c.track_id || c.tracking_id || c.id;
  const created = c.created_at || c.submitted_at;
  const hrs     = created ? hoursPending(created) : '—';

  return `
    <tr>
      <td style="padding:8px;border-bottom:1px solid #e2e8f0;">${trackId}</td>
      <td style="padding:8px;border-bottom:1px solid #e2e8f0;">${name}</td>
      <td style="padding:8px;border-bottom:1px solid #e2e8f0;">${email}</td>
      <td style="padding:8px;border-bottom:1px solid #e2e8f0;">${created ? new Date(created).toLocaleString() : '—'}</td>
      <td style="padding:8px;border-bottom:1px solid #e2e8f0;font-weight:600;color:#b91c1c;">${hrs}h</td>
    </tr>`;
}).join('');

const html = `
  <div style="font-family:Arial,sans-serif;max-width:640px;margin:0 auto;">
    <h2 style="color:#1e3a8a;">Pending Alumni Verification — Action Needed</h2>
    <p>${claims.length} verification claim(s) have been sitting in <strong>pending</strong>
       status for more than ${config.staleHours} hours. Please review and action them in
       the admin console.</p>
    <table style="width:100%;border-collapse:collapse;font-size:14px;">
      <thead>
        <tr style="background:#f1f5f9;text-align:left;">
          <th style="padding:8px;">Track ID</th>
          <th style="padding:8px;">Alumni</th>
          <th style="padding:8px;">Email</th>
          <th style="padding:8px;">Submitted</th>
          <th style="padding:8px;">Pending</th>
        </tr>
      </thead>
      <tbody>${rows}</tbody>
    </table>
    <p style="color:#64748b;font-size:12px;margin-top:16px;">
      This is an automated chaser sent every ${config.digestIntervalHours} hours by the
      Richfield Connect moderation workflow. It will keep sending until each claim's status
      changes away from "pending" - there is no snooze/dedup logic in this template (see
      README for how to add one if the repetition becomes noisy).
    </p>
  </div>`;

const recipients = (config.adminEmailsRaw || '')
  .split(',')
  .map(e => e.trim())
  .filter(Boolean);

return [{
  json: {
    html,
    subject: `⚠️ ${claims.length} alumni verification claim(s) pending 24h+`,
    recipients,
    fromAddress: config.fromAddress
  }
}];
